import React from 'react';
import {Composition, Still} from 'remotion';
import {Documentary} from './Documentary';
import {Thumbnail} from './Thumbnail';
import {Short, type ShortProps} from './Short';
import type {Timeline} from './types';
// Generated by pipeline/build_timeline.py — never edit by hand.
import timelineJson from '../public/timeline.json';

const timeline = timelineJson as unknown as Timeline;

export const RemotionRoot: React.FC = () => (
  <>
    <Composition
      id="Documentary"
      component={Documentary}
      durationInFrames={Math.max(1, timeline.durationInFrames)}
      fps={timeline.fps}
      width={timeline.width}
      height={timeline.height}
      defaultProps={{timeline}}
    />
    <Composition
      id="Short"
      component={Short}
      width={1080}
      height={1920}
      fps={25}
      durationInFrames={250}
      defaultProps={{src: 'shorts/seg.mp4', hook: 'Hook', words: [], durationInFrames: 250} as ShortProps}
      calculateMetadata={({props}) => ({durationInFrames: props.durationInFrames})}
    />
    <Still id="Thumb1" component={Thumbnail} width={1280} height={720} defaultProps={{variant: 1}} />
    <Still id="Thumb2" component={Thumbnail} width={1280} height={720} defaultProps={{variant: 2}} />
    <Still id="Thumb3" component={Thumbnail} width={1280} height={720} defaultProps={{variant: 3}} />
    <Still id="Thumb4" component={Thumbnail} width={1280} height={720} defaultProps={{variant: 4}} />
    <Still id="Thumb5" component={Thumbnail} width={1280} height={720} defaultProps={{variant: 5}} />
    <Still id="Thumb6" component={Thumbnail} width={1280} height={720} defaultProps={{variant: 6}} />
  </>
);
